# -*- coding: utf-8 -*-
"""Source of the translations. Every entry is
    E("English text", tr, de, fr, es, pt-BR, ru, zh-Hans)
Run `python3 tools/write_locales.py` to turn this into locales/<code>.json and
src/locales.ts. Keep {placeholders} exactly as in the English text.
"""
ORDER = ("tr", "de", "fr", "es", "pt-BR", "ru", "zh-Hans")
ENTRIES = []


def E(en, *tr):
    assert len(tr) == len(ORDER), en
    ENTRIES.append((en, tr))


